insert into public.butler_guide (id, ord, ver, n, t, ct, s, k, w, p) values
('s1', 1, '0.1.21', '1', 'Giới thiệu và cài đặt', 'Giới thiệu và cài đặt', 'WorkHub Fin là ứng dụng máy tính (Windows) giúp một nhóm đầu tư cổ phiếu Việt Nam quản lý danh mục và định giá chuyên môn trên cùng một bộ dữ liệu. Ứng dụng gồm hai khu độc lập, liên kết với nhau: Khu quản lý: danh mục, sổ lệnh, theo dõi, hiệu suất, rủi ro, giới hạn đầu tư…', '["Giới thiệu và cài đặt","quản lý danh mục","định giá chuyên môn","quản lý"]'::jsonb, 'chuyen mon|gia chuyen|cai dat|dinh gia|mon|hai khu|ly danh|khu|phan tich|quan ly|investment workbench|chuyen|du lieu|bench hien|bench khu|bo du|cao ca|chung du|doi hieu|dung gom', null),
('s1-1', 2, '0.1.21', '1.1', 'Cài đặt và cập nhật', 'Giới thiệu và cài đặt', 'Chạy tệp cài đặt WorkHub-Fin_0.1.21_x64-setup.exe (do quản trị nhóm gửi hoặc tải từ trang phát hành của dự án). Nếu Windows hiện cảnh báo SmartScreen, chọn Thông tin thêm → Vẫn chạy (ứng dụng nội bộ chưa có chứng chỉ thương mại). Mở WorkHub-Fin và đăng nhập bằng tài khoản…', '["Cài đặt và cập nhật","Thông tin thêm → Vẫn chạy","WorkHub-Fin","Kiểm tra cập nhật","Tải và cài đặt","Khởi động lại ngay","tự kiểm tra và cập nhật","tên tài khoản","quản lý tài sản","WorkHub-Fin_0.1.21_x64-setup.exe"]'::jsonb, 'cai dat|tu kiem|app|kiem tra|hop thoai|cap nhat|quan tri|tra cap|cai|workhub|moi|tri nhom|workhub fin|kiem|tra|ung dung|cap|thoai|tu|dat', null),
('s1-2', 3, '0.1.21', '1.2', 'Dữ liệu đến từ đâu', 'Giới thiệu và cài đặt', 'Các nguồn miễn phí không có cam kết dịch vụ: có thể đổi định dạng hoặc chặn bất cứ lúc nào. Ứng dụng kiểm tra chất lượng dữ liệu hằng ngày và báo "nguồn lỗi" ở tab Dữ Liệu của Toàn Nhóm khi có vấn đề. Mỗi ngày có dữ liệu mới, ứng dụng (bản desktop) tự lưu một tệp nén vào thư…', '["Dữ liệu đến từ đâu","Sao lưu & Phục hồi","Giá và nến ngày, VN-Index","Lợi suất trái phiếu chính phủ","đã điều chỉnh","không có cam kết dịch vụ"]'::jsonb, 'thu muc|du lieu|ngay|hang ngay|lieu|mien phi|vndirect|luu|nguon|ung dung|lich su|du|mien|app tren|chieu them|chinh nam|chinh phu|chup ca|dang hoac|dau du', null),
('s2', 4, '0.1.21', '2', 'Bắt đầu nhanh trong 10 phút', 'Bắt đầu nhanh trong 10 phút', 'Lộ trình ngắn nhất để thấy ứng dụng làm được gì: Vào Finance. Sau khi đăng nhập, thanh bên trái có nhóm Tài Chính với hai mục: Investment Workbench và Valuation Bench. Định giá một mã. Mở Valuation Bench, gõ mã (ví dụ FPT) ở ô tìm kiếm, nhấn Enter. Đợi vài giây để tải báo cáo…', '["Bắt đầu nhanh trong 10 phút","Tài Chính","Investment Workbench","Lưu bản định giá kèm hồ sơ quy trình","Nghiên Cứu → Chi tiết mã","Vào Finance.","Định giá một mã.","Đọc tab Tổng hợp.","Mở tab Quy trình.","Chỉnh giả định (tuỳ chọn).","Lưu bản định giá.","Quay lại Investment Workbench."]'::jsonb, 'dinh gia|gia|tab quy|dinh|quy trinh|tab|trinh|investment workbench|kinh doanh|ma|bench dinh|bien hoac|biet no|buoc sau|chinh nen|dat doc|dau nhanh|dinh tuy|doanh ket|doanh ma', null),
('s3', 5, '0.1.21', '3', 'Cách di chuyển trong ứng dụng', 'Cách di chuyển trong ứng dụng', 'Gồm: 3.1 Trang Finance và hai khu.', '["Cách di chuyển trong ứng dụng"]'::jsonb, 'hai khu|finance|ung dung|chuyen|khu|hai|ung|dung', null),
('s3-1', 6, '0.1.21', '3.1', 'Trang Finance và hai khu', 'Cách di chuyển trong ứng dụng', 'Trang Finance chính có thanh bên trái. Nhóm Tài Chính gồm: Pipeline, Investment Workbench, Valuation Bench, Market Simulation, Format Reports và Kế Toán (OnyxLine). Hai khu có thanh điều hướng riêng ở đầu trang; ở cả hai đều có lối sang khu kia.', '["Trang Finance và hai khu","Tài Chính","Investment Workbench","Market Simulation","mặt trăng","ngôi nhà","Quản gia","Market Simulation (mới 0.1.18)","#stock/FPT/process","Alt+J"]'::jsonb, 'valuation bench|hai khu|bench|khu|finance|valuation|market simulation|thanh dieu|quan gia|investment|tong quan|investment workbench|market|simulation|bench market|bench moi|bench valuation|biet moi|chinh gom|chung phuong', null),
('s4', 7, '0.1.21', '4', 'Investment Workbench', 'Investment Workbench', 'Khu quản lý đầu tư. Mỗi thành viên quản lý danh mục riêng; nhóm xem tổng hợp ở Toàn Nhóm.', '["Investment Workbench"]'::jsonb, 'quan ly|toan nhom|ly dau|muc rieng|rieng nhom|vien quan|khu quan|moi thanh|tt moi|tu moi|workbench khu|nhom|ly danh|quan tt|danh muc|quan|thanh vien|tong quan|tong|investment workbench', null),
('s4-1', 8, '0.1.21', '4.1', 'Danh Mục', 'Investment Workbench', 'Khi sàn mở (9:00 đến 11:30 và 13:00 đến 14:50), app lấy giá khớp gần nhất của các mã bạn đang nắm từ VNDirect, làm mới mỗi 20 giây, rồi cập nhật tại chỗ bảng danh mục, NAV, lãi/lỗ chưa thực hiện và lãi/lỗ trong ngày (so với giá tham chiếu). Dòng trạng thái phía trên bảng cho…', '["Danh Mục","Đăng nhập lại","Làm mới","Thu gọn","Báo biến động","Ẩn cảnh báo","Báo NAV giảm","Sổ Lệnh","Hiệu Suất","Gương","Rủi Ro","Báo Cáo"]'::jsonb, 'gia|app|muc|lai lo|lenh|phien|dang nam|moi|ma|danh muc|so|ke toan|hieu suat|ngay|dang|tham chieu|gia truc|canh|rui ro|lo', null),
('s4-2', 9, '0.1.21', '4.2', 'Nghiên Cứu', 'Investment Workbench', 'Trang nghiên cứu cổ phiếu. Các chế độ xem ở thanh trên cùng: Bảng so sánh (các mã bạn đã định giá, xếp Rẻ / Hợp lý / Đắt), Ý tưởng (đề xuất, bình luận, bỏ phiếu) và Chi tiết mã. Trong Chi tiết mã, ngay dưới phần đầu trang có thẻ Định giá chuyên môn (mới 0.1.10): giá trị hợp lý…', '["Nghiên Cứu","Bảng so sánh","Ý tưởng","Chi tiết mã","Định giá chuyên môn","tính theo giá hiện tại","Bộ lọc","Thị trường","Bản đồ","Định Giá CP","Tiêu chí:","từ 1/1 đến nay"]'::jsonb, 'bo loc|loc|ma|moi|bo|suc khoe|lot|gia|tieu|trung vi|nganh|so|moi lot|luu|da|dinh gia|dinh|so lieu|do|khoe', null),
('s4-3', 10, '0.1.21', '4.3', 'Toàn Nhóm', 'Investment Workbench', 'Ở Toàn Nhóm > Dữ Liệu có bảng Nguồn giá trực tiếp: hàm source-watch trên máy chủ gọi thử ba nguồn mà giá trực tiếp phụ thuộc (bảng giá VCI, VNDirect finfo, VNDirect dchart) mỗi 30 phút trong giờ giao dịch, hiện kết quả hôm nay, tỷ lệ 7 ngày, lần gần nhất và độ trễ trung bình…', '["Toàn Nhóm","Danh Mục Chung · Thành Viên","Định Lượng · Dữ Liệu","Khớp Lệnh · Hành Trình","Duyệt Lệnh","Chiến Lược · Hoạt Động · Báo Cáo","Nguồn giá trực tiếp","mỗi 30 phút trong giờ giao dịch","cảnh báo","hai ngày giao dịch liên tiếp","email quản lý","source-watch"]'::jsonb, 'ngay giao|quan ly|giao dich|hanh trinh|tham do|nguon|thanh vien|dinh luong|giao|khop lenh|luong du|lenh|ngay|dich|gia truc|gia vci|du lieu|nhom|bang gia|muc', null),
('s4-4', 11, '0.1.21', '4.4', 'Tổng Quan TT (mới)', 'Investment Workbench', 'Trang xem nhanh thị trường chung ngay cạnh Toàn Nhóm, để theo dõi trong ngày mà không phải mở từng mã. Tên Tổng Quan TT để khỏi nhầm với mục Thị trường (bộ lọc cổ phiếu) trong Valuation Bench. Mỗi thẻ ghi số liệu của lúc nào, từ nguồn nào, trễ bao lâu (ví dụ "Số liệu lúc 09:09…', '["Tổng Quan TT","Thị trường","Làm mới","Tóm tắt tin hôm nay","Năm chỉ số và biểu đồ","Độ rộng và thanh khoản","Cổ phiếu nổi bật","Hiệu suất, xu hướng kỹ thuật","Tác động lên chỉ số","Ngành, định giá thị trường","Tin thị trường","Ước tính"]'::jsonb, 'so|phut|bang gia|gio|dong len|nganh|moi|so nganh|tin|phien|do rong|ghi gio|ngoai mua|noi bat|phieu noi|ta ngan|tat tin|tu chuyen|tu|tac dong', null),
('s5', 12, '0.1.21', '5', 'Valuation Bench: tổng quan', 'Valuation Bench: tổng quan', 'Valuation Bench là khu để định giá chuyên môn một cổ phiếu: kết hợp phân tích cơ bản, nhiều phương pháp định giá, phân tích kỹ thuật và bối cảnh thị trường thành một kết luận có giải thích, được tạo theo một quy trình có ghi vết.', '["Valuation Bench: tổng quan","định giá chuyên môn một cổ phiếu"]'::jsonb, 'phan tich|tong quan|hop phan|nhieu phuong|phieu ket|quan valuation|tao theo|valuation bench|bay tab|bench tong|bon con|phap dinh|doc dung|ghi vet|gia phan|truong thanh|bench|chuyen mon|gia chuyen|tich', null)
insert into public.butler_guide (id, ord, ver, n, t, ct, s, k, w, p) values
('s5-1', 13, '0.1.21', '5.1', 'Tổng quan', 'Valuation Bench: tổng quan', 'Trang đầu có ô tìm mã, các mã xem gần đây, bản tóm tắt mặt bằng định giá thị trường so với lịch sử, và danh sách các bản định giá đã lưu của cả nhóm (mã, giá trị hợp lý, người lập, ngày).', '["Tổng quan"]'::jsonb, 'gan day|lap ngay|nhom ma|tat mat|truong so|ly nguoi|ma gia|gia da|nguoi lap|dinh gia|mat bang|bang dinh|ma|tom tat|tong quan|ca nhom|danh sach|da luu|tom|gia', null),
('s5-2', 14, '0.1.21', '5.2', 'Hồ sơ cổ phiếu và bảy tab', 'Valuation Bench: tổng quan', 'Tổng hợp Giá trị hợp lý đồng thuận và dải, giá hiện tại, biên an toàn, độ tin cậy, điểm kỹ thuật và thị trường; biểu đồ khoảng giá của từng phương pháp; vùng giá tham khảo; lý do chính; cờ cần soát. Có banner trạng thái quy trình. Quy trình Bảy bước ghi vết (xem mục 6). Cơ bản…', '["Hồ sơ cổ phiếu và bảy tab","Tổng hợp","Cơ bản","Thị trường","biên an toàn"]'::jsonb, 'ky thuat|diem ky|dong|thuat|so|ngan hang|tong hop|gia|bay buoc|beneish sloan|buoc ghi|cao piotroski|carlo kich|cay diem|chinh nhieu|cu mau|dai gia|dinh xoa|dong ho|dong rieng', null),
('s5-3', 15, '0.1.21', '5.3', 'Bốn con số cần đọc đúng', 'Valuation Bench: tổng quan', 'Giá trị hợp lý (đồng thuận) Trung vị có trọng số của giá trị mà từng phương pháp cho ra. Dùng trung vị để một phương pháp lệch xa không kéo cả kết quả. Dải là trung bình có trọng số của đầu thấp và đầu cao. Biên an toàn 1 − giá / giá trị hợp lý. Dương nghĩa là giá thấp hơn giá…', '["Bốn con số cần đọc đúng"]'::jsonb, 'gia tri|gia|gia thap|tri uoc|tri|phuong phap|hon gia|trung vi|uoc tinh|tri hop|thap hon|hop ly|phuong|trung|thap|phap|bay gia|beneish diem|ca ket|dat mac', null),
('s6', 16, '0.1.21', '6', 'Quy trình định giá 7 bước', 'Quy trình định giá 7 bước', 'Thay vì chạy mọi phương pháp rồi lấy trọng số cố định, mỗi lần định giá đi qua một quy trình. Quy trình không đưa ra khuyến nghị: nó bảo đảm mỗi con số có lý do được chọn, có giới hạn được nêu và có kiểm tra chéo. Mở tab Quy trình; thanh tiến độ ở đầu cho thấy từng bước xanh…', '["Quy trình định giá 7 bước","không đưa ra khuyến nghị"]'::jsonb, 'tung buoc|quy trinh|trinh|buoc|buoc xanh|chay moi|dam moi|dat vang|lan dinh|lay trongso|nghi no|phap roi|ra khuyen|roi lay|trinh thanh|vang canh|vi chay|xanh dat|quy|dinh moi', null),
('s6-1', 17, '0.1.21', '6.1', 'Từng bước', 'Quy trình định giá 7 bước', 'Ví dụ DCF và P/E ngành lệch nhau hơn 50% là chuyện thường gặp ở doanh nghiệp tăng trưởng. Quy trình không bác bỏ kết quả; nó buộc bạn giải thích vì sao chấp nhận chênh lệch đó (hợp đồng đã ký, giả định nào khác ngành), và lý do được lưu cùng bản định giá.', '["Từng bước","Phân loại mô hình kinh doanh","Bạn có thể chọn lại","Cổng dữ liệu","Kế hoạch phương pháp","Backtest","lỗ hổng","Giả định và nguồn gốc","Chạy và đối chiếu chéo","Kiểm tra hợp lý","Kết luận và hồ sơ quyết định","Quy trình hoàn tất"]'::jsonb, 'phuong phap|ly do|dong thuan|phuong|phap|so|phap chinh|tang truong|gia|bat dong|lech|dinh so|ky gia|do|ket luan|nganh|dinh|ly|gia tri|gia dinh', null),
('s6-2', 18, '0.1.21', '6.2', 'Trọng số đi đâu?', 'Quy trình định giá 7 bước', 'Trọng số theo vai trò là mặc định. Ở tab Tổng hợp, cột trọng số cho phép chỉnh tay từng phương pháp; lựa chọn thủ công thắng quy trình. Nút "Về mặc định của quy trình" ở bước 3 xoá mọi đổi vai trò.', '["Trọng số đi đâu?","Tổng hợp","lựa chọn thủ công thắng quy trình"]'::jsonb, 'mac dinh|trongso|chinh tay|cong thang|cot trongso|hop cot|moi doi|phap lua|phep chinh|tay tung|theo vai|xoa moi|vai tro|chon thu|lua chon|thang quy|trongso theo|trongso trongso|ve mac|quy trinh', null),
('s7', 19, '0.1.21', '7', 'Tab Định giá: DCF, bội số, tài sản', 'Tab Định giá: DCF, bội số, tài sản', 'Gồm: 7.1 DCF dòng tiền doanh nghiệp (FCFF) · 7.2 Ngân hàng, chứng khoán, bảo hiểm · 7.3 Bội số: so với ngành và với lịch sử · 7.4 Phương pháp tài sản, thu nhập và cổ tức.', '["Tab Định giá: DCF, bội số, tài sản","Tab Định giá"]'::jsonb, 'dcf boi|boi so|gia dcf|hang chung|dcf dong|nghiep fcff|san thu|so so|tab dinh|tien doanh|dcf|chung khoan|thu nhap|boi|ngan hang|san|hiem|so|doanh nghiep|fcff', null),
('s7-1', 20, '0.1.21', '7.1', 'DCF dòng tiền doanh nghiệp (FCFF)', 'Tab Định giá: DCF, bội số, tài sản', 'Dành cho doanh nghiệp phi tài chính. Ứng dụng dựng giả định mặc định từ chính lịch sử của doanh nghiệp: biên EBIT bình quân 3 năm, tăng trưởng giai đoạn đầu (60% CAGR doanh thu + 40% tăng trưởng bền vững, kẹp 2%–20%), thuế hội tụ về 20%, WACC theo CAPM (beta điều chỉnh Blume…', '["DCF dòng tiền doanh nghiệp (FCFF)","Bảng nhạy cảm","Monte Carlo","DCF ngược","Kịch bản"]'::jsonb, 'tang truong|phan phoi|mac dinh|tang|wacc|gia hien|doanh nghiep|dung gia|mac|phoi|dinh|doanh|gia|bang nhay|beta dieu|bien tang|blume phan|bu rui|cagr doanh|cam wacc', null),
('s7-2', 21, '0.1.21', '7.2', 'Ngân hàng, chứng khoán, bảo hiểm', 'Tab Định giá: DCF, bội số, tài sản', 'Nợ là nguyên liệu kinh doanh nên không dùng dòng tiền doanh nghiệp. Thay vào đó: thu nhập thặng dư, P/B hợp lý = (ROE − g)/(Ke − g), FCFE nhiều giai đoạn và mô hình cổ tức; các giả định ROE, g, Ke, tỷ lệ chi trả chỉnh được.', '["Ngân hàng, chứng khoán, bảo hiểm","thu nhập thặng dư","P/B hợp lý","FCFE"]'::jsonb, 'dinh roe|do thu|hiem no|ke ty|tra chinh|roe|doanh nen|dung dong|lieu kinh|nguyen lieu|fcfe nhieu|hang chung|ly roe|nhap thang|nhieu giai|thang du|tien doanh|chung khoan|ke|thu nhap', null),
('s7-3', 22, '0.1.21', '7.3', 'Bội số: so với ngành và với lịch sử', 'Tab Định giá: DCF, bội số, tài sản', 'Bảng bội số hiện tại (P/E, P/B, P/S, EV/EBITDA, EV/EBIT, EV/Doanh thu...) với trung vị ngành, phân vị trong ngành (0 = rẻ nhất ngành) và dải 5 năm của chính cổ phiếu. Bên dưới là giá ngầm định khi áp bội số phân vị 20/50/80 của ngành hoặc của lịch sử vào số liệu của mã. Ngân…', '["Bội số: so với ngành và với lịch sử","phân vị trong ngành"]'::jsonb, 'nganh|boi so|ev|ebitda|phan vi|tinh tu|ev doanh|so|ev ebitda|boi|ngan hang|ap boi|bang boi|cao nen|dinh khi|ebit ev|ebitda hoat|ev ebit|hai boi|hiem chung', null),
('s7-4', 23, '0.1.21', '7.4', 'Phương pháp tài sản, thu nhập và cổ tức', 'Tab Định giá: DCF, bội số, tài sản', 'Giá trị sức sinh lời (EPV), số Graham và công thức tăng trưởng của Graham, PEG của Lynch, mô hình cổ tức, NCAV, giá trị sổ sách và Tobin''s Q; NAV (điều chỉnh đánh giá lại tài sản) và SOTP (tổng các phần) do bạn nhập.', '["Phương pháp tài sản, thu nhập và cổ tức","SOTP"]'::jsonb, 'graham|chinh danh|nav dieu|ncav gia|phan do|sotp tong|tuc ncav|graham peg|tuc gia|tobin|epv so|loi epv|thuc tang|san thu|so graham|cong thuc|gia lai|sinh loi|so sach|suc sinh', null),
('s8', 24, '0.1.21', '8', 'Ba công cụ làm sâu định giá', 'Ba công cụ làm sâu định giá', 'Gồm: 8.1 DCF theo động lực · 8.2 Bộ mã so sánh tự chọn · 8.3 Điều chỉnh khoản bất thường.', '["Ba công cụ làm sâu định giá"]'::jsonb, 'ba cong|sau dinh|chinh khoan|cong cu|sanh tu|bo ma|bat thuong|khoan bat|theo dong|dcf theo|tu chon|dong luc|ma so|ba|so sanh|dieu chinh|sanh|dinh gia|dcf|thuong', null)
insert into public.butler_guide (id, ord, ver, n, t, ct, s, k, w, p) values
('s8-1', 25, '0.1.21', '8.1', 'DCF theo động lực', 'Ba công cụ làm sâu định giá', 'DCF mặc định ngoại suy từ lịch sử. Khi bạn có luận điểm cụ thể (công suất mới, hợp đồng đã ký, một mảng đang tăng tốc hoặc suy giảm), hãy dựng dự báo riêng: Tích Dùng DCF theo động lực. Mẫu một mảng "Toàn công ty" được điền sẵn từ lịch sử. Sửa tên mảng, doanh thu cơ sở (tỷ)…', '["DCF theo động lực","Dùng DCF theo động lực","Thêm mảng","doanh thu cơ sở (tỷ)","đường tăng trưởng theo năm","biên EBIT"]'::jsonb, 'doanh thu|luu dong|tri cuoi|von luu|tang truong|mang|duong tang|ngoai suy|them mang|capex|tang|suy|capex von|theo nam|doanh|cuoi ky|truong dai|tu lich|cuoi|khau hao', null),
('s8-2', 26, '0.1.21', '8.2', 'Bộ mã so sánh tự chọn', 'Ba công cụ làm sâu định giá', 'Ngành ICB cấp 2 rất rộng (ví dụ "Công nghệ" gồm phần mềm, viễn thông, bán lẻ thiết bị...). Trong thẻ Bộ mã so sánh chọn Tự chọn mã, nhập các đối thủ trực tiếp (từ 3 mã, cách nhau dấu phẩy hoặc khoảng trắng) rồi Áp dụng bộ này. Nút Lấy 10 mã lớn nhất cùng ngành cho điểm xuất…', '["Bộ mã so sánh tự chọn","Bộ mã so sánh","Tự chọn mã","Áp dụng bộ này","Lấy 10 mã lớn nhất cùng ngành"]'::jsonb, 'tu chon|bo|ma|so sanh|thong ke|chon|bo ma|ma so|sanh|bang hien|bo theo|bo tu|chon bo|chon nganh|chu bo|diem xuat|dinh quy|du boi|du cong|gom phan', null),
('s8-3', 27, '0.1.21', '8.3', 'Điều chỉnh khoản bất thường', 'Ba công cụ làm sâu định giá', 'Lợi nhuận kế toán có thể chứa khoản một lần (hoàn nhập dự phòng, lãi bán đầu tư, thanh lý tài sản) làm P/E thấp hoặc cao giả tạo. Thẻ Điều chỉnh khoản bất thường cho phép loại chúng khỏi kỳ cơ sở (4 quý gần nhất hoặc năm gần nhất): Dưới EBIT (lãi bán đầu tư, đánh giá lại): chỉ…', '["Điều chỉnh khoản bất thường","Dưới EBIT","Trong EBIT","âm","gợi ý"]'::jsonb, 'loi nhuan|bien dcf|hoan nhap|nhap du|thanh ly|nhuan|thue|chinh khoan|sau thue|thue suat|so tien|ebit|dieu chinh|hoan|bat thuong|khoan bat|loi|nhap|xa|du phong', null),
('s9', 28, '0.1.21', '9', 'Kỹ thuật, thị trường và kết luận kết hợp', 'Kỹ thuật, thị trường và kết luận kết hợp', 'Gồm: 9.1 Phân tích kỹ thuật · 9.2 Bối cảnh thị trường · 9.3 Kết luận kết hợp.', '["Kỹ thuật, thị trường và kết luận kết hợp"]'::jsonb, 'luan ket|ket hop|ky thuat|ket luan|ket|thuat|tich ky|luan|phan tich|ky|boi canh|hop|truong|tich|boi|canh|phan', null),
('s9-1', 29, '0.1.21', '9.1', 'Phân tích kỹ thuật', 'Kỹ thuật, thị trường và kết luận kết hợp', 'Tab Kỹ thuật tính từ nến ngày: đường trung bình, RSI, MACD, Stochastic, CCI, ADX, Bollinger/Keltner/Donchian, OBV, MFI, CMF, VWAP, Aroon, Supertrend/Parabolic SAR, Ichimoku, biến động và sụt giảm, điểm xoay và Fibonacci, hỗ trợ/kháng cự theo cụm, mẫu nến, phân kỳ, sức mạnh…', '["Phân tích kỹ thuật","Điểm kỹ thuật"]'::jsonb, 'ky thuat|thuat|adx bollinger|aroon supertrend|binh rsi|cci adx|cmf vwap|cum mau|donchian obv|fibonacci ho|giam diem|gop xu|ichimoku bien|mfi cmf|ngay duong|obv mfi|rsi macd|sar ichimoku|stochastic cci|supertrend parabolic', null),
('s9-2', 30, '0.1.21', '9.2', 'Bối cảnh thị trường', 'Kỹ thuật, thị trường và kết luận kết hợp', 'Tab Thị trường đo mặt bằng định giá của thị trường và ngành so với lịch sử, so với lợi suất trái phiếu, vòng quay sức mạnh ngành, dòng tiền khối ngoại, thanh khoản và beta. Điểm trên +30 là gió thuận, dưới −30 là gió ngược.', '["Bối cảnh thị trường","Thị trường"]'::jsonb, 'beta diem|diem tren|phieu vong|su so|thuan duoi|truong tab|do mat|gio nguoc|gio thuan|manh nganh|nganh dong|quay suc|suat trai|nganh so|ngoai thanh|trai phieu|truong do|gio|tien khoi|vong quay', null),
('s9-3', 31, '0.1.21', '9.3', 'Kết luận kết hợp', 'Kỹ thuật, thị trường và kết luận kết hợp', 'Điểm kết hợp = 50% định giá + 30% kỹ thuật + 20% thị trường, rồi đối chiếu theo bảng quy tắc cố định (rẻ/đắt × xu hướng giá × bối cảnh) ra nhận định bằng lời. Kỹ thuật và thị trường chỉ cho biết thời điểm, không thay giá trị hợp lý.', '["Kết luận kết hợp","thời điểm"]'::jsonb, 'ket hop|ky thuat|bang loi|biet thoi|canh ra|chieu theo|diem ket|hop diem|loi ky|ra nhan|roi doi|dat xu|dinh bang|dinh re|gia boi|theo bang|truong roi|bang quy|nhan dinh|thuat', null),
('s10', 32, '0.1.21', '10', 'Lưu, nạp lại và áp dụng vào danh mục', 'Lưu, nạp lại và áp dụng vào danh mục', 'Gồm: 10.1 Lưu bản định giá · 10.2 Nạp lại giả định · 10.3 Áp dụng vào danh mục.', '["Lưu, nạp lại và áp dụng vào danh mục"]'::jsonb, 'nap lai|ap dung|nap|luu nap|ap|lai gia|danh muc|luu|gia dinh|danh|lai|muc|dinh|dung|dinh gia|gia', null),
('s10-1', 33, '0.1.21', '10.1', 'Lưu bản định giá', 'Lưu, nạp lại và áp dụng vào danh mục', 'Mỗi lần lưu là một bản ghi mới, không sửa được (lịch sử bất biến), gồm giá trị hợp lý và dải, vùng giá, phương pháp và trọng số, giả định, hồ sơ quy trình (mô hình, vai trò, kết quả kiểm tra, lỗ hổng, lý do chấp nhận), lựa chọn điều chỉnh/bộ so sánh/động lực, và ghi chú của…', '["Lưu bản định giá","bản ghi mới, không sửa được"]'::jsonb, 'bat bien|bien gom|chon dieu|dai vung|dinh ho|ghi moi|gia phuong|gom gia|hong ly|lap quan|nhan lua|su bat|tra lo|tro ket|trongso gia|vien xoa|chinh bo|hoac quan|lan luu|lua chon', null),
('s10-2', 34, '0.1.21', '10.2', 'Nạp lại giả định', 'Lưu, nạp lại và áp dụng vào danh mục', 'Ở tab Đã lưu, nút nạp lại đưa mọi giả định của một bản về trạng thái lúc lưu (DCF, ngân hàng, trọng số, biên an toàn, vai trò quy trình, điều chỉnh, bộ so sánh, động lực) để tiếp tục chỉnh hoặc đối chiếu.', '["Nạp lại giả định"]'::jsonb, 'nap lai|nap|dcf ngan|dua moi|hang trongso|hoac doi|luu dcf|moi gia|tab da|thai luc|tiep tuc|toan vai|trinh dieu|tro quy|trongso bien|tuc chinh|gia dinh|chinh bo|chinh hoac|lai dua', null),
('s10-3', 35, '0.1.21', '10.3', 'Áp dụng vào danh mục', 'Lưu, nạp lại và áp dụng vào danh mục', 'Nút Áp dụng vào danh mục ghi giá mục tiêu (giá trị hợp lý đồng thuận) và giá muốn mua (đầu trên của vùng tích luỹ) cho mã trong Danh Mục / Theo Dõi của bạn, sau khi hỏi xác nhận. Cảnh báo giá chạy như cũ.', '["Áp dụng vào danh mục","giá mục tiêu","giá muốn mua"]'::jsonb, 'ap dung|ghi gia|gia chay|hoi xac|khi hoi|mua dau|danh muc|dau tren|gia muc|nhan canh|tieu gia|ap|muc ghi|muc theo|muc tieu|muc|ly dong|vung tich|xac nhan|dong thuan', null),
('s11', 36, '0.1.21', '11', 'Bảng điểm độ chính xác', 'Bảng điểm độ chính xác', 'Trang Độ chính xác trả lời câu hỏi "bộ máy này đã đúng đến đâu trong quá khứ?".', '["Bảng điểm độ chính xác","Độ chính xác"]'::jsonb, 'hoi bo|xac tra|do chinh|chinh xac|qua hien|tinh ngay|loi cau|bang diem|da dung|diem do|bo may|qua khu|cau hoi|tra loi|xac|tinh|qua|cau|chinh|ket qua', null)
insert into public.butler_guide (id, ord, ver, n, t, ct, s, k, w, p) values
('s11-1', 37, '0.1.21', '11.1', 'Cách tính', 'Bảng điểm độ chính xác', 'Tại mỗi tháng trong quá khứ, bộ máy được chạy lại chỉ với dữ liệu có sẵn lúc đó (báo cáo đã công bố sau độ trễ, chuỗi bội số đến ngày đó, giá ngày đó), rồi so giá trị hợp lý với lợi suất 6 và 12 tháng sau trừ lợi suất VN-Index.', '["Cách tính","chỉ với dữ liệu có sẵn lúc đó"]'::jsonb, 'ngay do|bo sau|cao da|chuoi boi|do roi|gia ngay|khu bo|moi thang|san luc|sau tru|tre chuoi|tru loi|loi suat|chay lai|da cong|do gia|luc do|roi so|suat vn|chuoi', null),
('s11-2', 38, '0.1.21', '11.2', 'Cách đọc', 'Bảng điểm độ chính xác', 'IC (hệ số tương quan hạng): mã được định giá thấp hơn giá trị hợp lý có vượt thị trường sau đó không. 0 = không có thông tin, +1 = hoàn hảo. Với dữ liệu thị trường, +0,05 đến +0,10 đã đáng kể; trên +0,20 là rất tốt. Khoảng tin cậy 95% trong ngoặc vuông: chứa 0 nghĩa là chưa…', '["Cách đọc","IC","Khoảng tin cậy 95%","5 nhóm rẻ/đắt","Từng phương pháp / từng mô hình","Ngoài mẫu"]'::jsonb, 'nhom re|ic|phuong phap|bo may|tung phuong|phuong|nhom|phap|canh tung|chon vai|dang ke|dat neu|doc ic|gian sau|hien ic|hoan hao|ke tren|ma du|mau ic|may manh', null),
('s11-3', 39, '0.1.21', '11.3', 'Kết quả hiện tại (tính ngày 06/10/2026)', 'Bảng điểm độ chính xác', 'Chỉ một chu kỳ thị trường (2020–2026); tập mã là mã đã thành công (thiên lệch người sống sót và nhìn trước); giá đã điều chỉnh; các quan sát chồng lấn nên số mẫu độc lập ít hơn con số "mẫu" hiển thị nhiều. Không đo được phần so sánh với ngành, kỹ thuật và bối cảnh thị trường…', '["Kết quả hiện tại (tính ngày 06/10/2026)","Độ chính xác","Phạm vi","IC 12 tháng","IC 6 tháng","Ngoài mẫu (T sau 12/2023)","Nhóm rẻ nhất so với đắt nhất","một chu kỳ thị trường","ngoài mẫu gần như không đổi","bác bỏ","giữ nguyên"]'::jsonb, 'giai doan|hai giai|ic|ngoai mau|doan|mau|chinh do|huan luyen|so mau|tren giai|giai|ky han|quan sat|nhom|huan|luyen|ca hai|chu ky|hieu chinh|hoc', null),
('s12', 40, '0.1.21', '12', 'Ví dụ làm từ đầu đến cuối', 'Ví dụ làm từ đầu đến cuối', 'Ví dụ minh hoạ với số liệu ngày 05/10/2026; con số thực sẽ khác khi bạn dùng. Mục đích là cho thấy cách đọc, không phải kết luận về FPT. Tìm mã. Valuation Bench → gõ FPT. Tab Tổng hợp cho giá trị hợp lý đồng thuận cao hơn giá nhiều; độ tin cậy "Vừa"; nhận định "Rẻ nhưng giá…', '["Ví dụ làm từ đầu đến cuối","Tìm mã.","Mở Quy trình.","bất đồng","Soát giả định.","DCF theo động lực","bộ mã so sánh tự chọn","Xem lại quy trình.","FPT"]'::jsonb, 'cao hon|gia|dcf|gia dinh|dinh tang|hon nhieu|dinh|nhieu so|phap chinh|vi|theo gia|nganh|hon|tang truong|cao|tang|quy trinh|vi du|thap hon|chenh', null),
('s13', 41, '0.1.21', '13', 'Giới hạn và nguyên tắc dùng đúng', 'Giới hạn và nguyên tắc dùng đúng', 'Cho một ước tính có giải thích, có ghi vết và có kiểm tra chéo. Xếp hạng mã rẻ/đắt tốt hơn đoán mò (theo backtest). Cho thấy giả định nào làm kết quả đổi nhiều nhất. Dự báo giá hoặc bảo đảm lợi nhuận. Chỉ khoảng 19% giá trị hợp lý nằm trong ±20% so với giá 12 tháng sau (sai số…', '["Giới hạn và nguyên tắc dùng đúng"]'::jsonb, 'nguyen tac|cong cu|bo nguyen|cheo xep|dam loi|dao nganh|dat tot|doan ve|doi nhieu|dung cong|hoac khoan|ly nam|ly phat|ma re|nganh phap|nhieu nhat|phat hien|qua doi|sau sai|theo backtest', null),
('s13-x1', 42, '0.1.21', '', 'Nguyên tắc', 'Giới hạn và nguyên tắc dùng đúng', 'Luôn đọc độ tin cậy, trạng thái quy trình và các cờ trước khi nhìn giá trị hợp lý. Đối chiếu số liệu quan trọng với báo cáo gốc (đặc biệt số cổ phiếu, nợ, khoản bất thường). Không dùng một phương pháp: tìm hai cách nhìn độc lập cùng dẫn tới một vùng giá.', '["Nguyên tắc","độ tin cậy","trạng thái quy trình"]'::jsonb, 'nghi ngo|ngo|nhin|truoc khi|cao moi|chieu so|cu hon|dac biet|doc do|goc dac|khi chap|khi nghi|khi nhin|lai khi|lap cung|luon doc|ly ngoai|nhan ket|nhin doc|nhin gia', null),
('s14', 43, '0.1.21', '14', 'Xử lý sự cố và câu hỏi thường gặp', 'Xử lý sự cố và câu hỏi thường gặp', '"Không tải được <mã>" ở Valuation Bench Nguồn dữ liệu không phản hồi hoặc mã sai. Bấm Tải lại dữ liệu; kiểm tra mã; xem tab Dữ Liệu của Toàn Nhóm có cảnh báo nguồn không. "Thiếu dữ liệu then chốt" ở bước 2 Mã mới niêm yết (dưới 3 năm báo cáo) hoặc thiếu giá/số cổ phiếu. Giá trị…', '["Xử lý sự cố và câu hỏi thường gặp","Tải lại dữ liệu","Kiểm tra hệ thống","Chạy kiểm tra","Gửi thông báo thử","Sao chép báo cáo","Thử lại","\"Không tải được <mã>\" ở Valuation Bench","\"Thiếu dữ liệu then chốt\" ở bước 2","Phương pháp so với ngành biến mất","Chưa lưu được vì \"còn mục chưa đạt\"","Huy hiệu định giá không hiện ở Danh Mục"]'::jsonb, 'nguon|du lieu|gia truc|lieu|hoac|kiem tra|gia|truc tiep|khoa ai|du|chua|kiem|phuong phap|app|dang nhap|chup|thong|chay kiem|chua so|ghi tep', null),
('s14-x1', 44, '0.1.21', '', 'Không Gian Riêng', 'Xử lý sự cố và câu hỏi thường gặp', 'Ngoài phần tài chính, ứng dụng còn có Không Gian Riêng (tổng quan "Hôm nay", lịch riêng đồng bộ Google Calendar, việc riêng, ghi chú, đồng bộ thư mục). Phần này không thuộc hướng dẫn này; sau khi cập nhật có thể cần bấm lại Kết nối Google Calendar.', '["Không Gian Riêng","Kết nối Google Calendar"]'::jsonb, 'google calendar|gian rieng|calendar|dong bo|rieng|google|gian|bam lai|bo google|bo thu|calendar viec|lai ket|lich rieng|muc phan|ngoai phan|noi google|quan hom|rieng dong|rieng ghi|rieng ngoai', null),
('s15', 45, '0.1.21', '15', 'Market Simulation: mô phỏng xác suất (mới 0.1.18)', 'Market Simulation: mô phỏng xác suất (mới 0.1.18)', 'Market Simulation trả lời câu hỏi: trong 1 tuần, 1 tháng, 3 tháng tới, VN-Index và danh mục của tôi có thể đi những đường nào, với xác suất bao nhiêu, và nên xử lý thế nào ở từng nhánh? Khu riêng có accent tím mực; lối vào ở thanh bên Finance và mục cuối thanh điều hướng của…', '["Market Simulation: mô phỏng xác suất","Market Simulation","Kiểm chứng","Triển vọng","Lưu triển vọng để tự chấm điểm","Lấy bối cảnh bằng AI","Thêm sự kiện tự nhập","Mô phỏng","Cây kịch bản","theo mô hình","xác suất và độ lớn cú sốc do bộ máy tính","cây theo sự kiện"]'::jsonb, 'su kien|xac suat|cham diem|nhanh|tu cham|kien|su|cu soc|vn index|khau vi|tinh ca|tung nhanh|do|kiem chung|xac|xu ly|suat|soc|cay song|ke hoach', null),
('s15-1', 46, '0.1.21', '15.1', 'Lưu lần chạy và tự chấm điểm', 'Market Simulation: mô phỏng xác suất (mới 0.1.18)', 'Sau khi chạy ở Mô phỏng (hoặc ở Triển vọng), bấm Lưu vào nhật ký mô phỏng, ghi một dòng lý do nếu muốn. Dự báo đã lưu không sửa được để chấm công bằng; chỉ sửa ghi chú, tên và đánh dấu sự kiện. Khi đủ 5 / 21 / 63 phiên giao dịch sau ngày dữ liệu của lần chạy, mục Nhật ký tự so…', '["Lưu lần chạy và tự chấm điểm","Mô phỏng","Triển vọng","Lưu vào nhật ký mô phỏng","Ghi vào Nhật Ký Quyết Định","không sửa được","Dự báo đã lưu đúng đến đâu","Có bối cảnh / chỉ lịch sử"]'::jsonb, 'lan chay|chay|tot hon|lan|so lan|khoang|nhanh|thuc te|nhat ky|tot|luu|phong|quyet dinh|bam ghi|bss duong|canh ai|cham cong|chay muc|chay neu|chu ten', null),
('s15-2', 47, '0.1.21', '15.2', 'Cây sống và máy chủ theo dõi', 'Market Simulation: mô phỏng xác suất (mới 0.1.18)', 'Cây sống: khi các mốc trôi qua, trang biết thị trường đã đi nhánh nào và hiện xác suất có điều kiện của các nhánh còn lại (đọc từ cây đã lưu, không mô phỏng lại). Đánh dấu một sự kiện "Đã xảy ra" / "Không xảy ra" thì cây sống chuyển sang cây theo sự kiện đó.', '["Cây sống và máy chủ theo dõi","Xác nhận","Cây sống:","có điều kiện","Máy chủ theo dõi mỗi ngày làm việc","mới tới mốc","AI đọc tin cho sự kiện:","AI đọc tin","chỉ là gợi ý"]'::jsonb, 'cay song|doc tin|su kien|song|ai doc|ai|cay|lan chay|xay ra|kien|chu theo|da xay|moc|xay|tin|xac nhan|doc|danh dau|may chu|su', null),
('s15-3', 48, '0.1.21', '15.3', 'Cân bằng lại theo tối ưu hoá (mới 0.1.20)', 'Market Simulation: mô phỏng xác suất (mới 0.1.18)', 'Ở Mô phỏng có thêm ba cách xử lý Cân bằng lại, đưa tỷ trọng các mã về mức tối ưu của tab Rủi Ro (cùng bộ ước lượng, đã đối chiếu thư viện khoa học) rồi so với giữ nguyên, cắt lỗ, chốt lời... trên cùng các đường giá: Ít biến động nhất: danh mục ít dao động nhất trong giới hạn tỷ…', '["Cân bằng lại theo tối ưu hoá","Mô phỏng","Rủi Ro","Tạo chính sách của riêng bạn","Cân bằng lại","Ít biến động nhất","Cân bằng rủi ro","Sharpe tối đa","chính tiền vừa bán"]'::jsonb, 'bang lai|duong gia|uu|it|dong nhat|lai theo|rui ro|uu hoa|moi ma|bang|ma|rui|bien dong|bi bo|bi dung|bo kem|bo uoc|chieu thu|chinh tien|chiu bien', null)
insert into public.butler_guide (id, ord, ver, n, t, ct, s, k, w, p) values
('s15-4', 49, '0.1.21', '15.4', 'Học độ lớn cú sốc từ kết quả thật (mới 0.1.20)', 'Market Simulation: mô phỏng xác suất (mới 0.1.18)', 'Độ lớn cú sốc của một sự kiện lúc đầu lấy từ lịch sử VN-Index. Khi bạn đánh dấu sự kiện ở Nhật ký là đã xảy ra và mốc của nó đã tới, ứng dụng so lợi suất VN-Index thật với độ lớn đã đặt và học một hệ số nhân theo loại sự kiện (chính sách, quốc tế,...). Bảng Độ lớn cú sốc: kết…', '["Học độ lớn cú sốc từ kết quả thật","Giả định mô phỏng","Dùng độ lớn cú sốc đã học từ Nhật ký","đã xảy ra","theo loại sự kiện"]'::jsonb, 'do lon|cu soc|he so|soc|su kien|lon|lon cu|hoc tu|he|kien|moc|hoc|that|do|so|lon da|luu sat|nhieu thang|sat nhau|truong nen', null),
('s16', 50, '0.1.21', '16', 'Insight: chín công cụ phân tích sâu (mới 0.1.20)', 'Insight: chín công cụ phân tích sâu (mới 0.1.20)', 'Trang Insight (thanh điều hướng của Investment Workbench) gom chín công cụ bổ sung cho các trang đã có. Mọi công cụ mô tả và cảnh báo theo điều kiện bạn đặt, không phải khuyến nghị đầu tư; mỗi mục ghi số liệu tính đến lúc nào.', '["Insight: chín công cụ phân tích sâu","Insight","Việc cần làm","Luận điểm","Sở hữu","Luân chuyển ngành","Độ chính xác","Kho dữ liệu","mô tả và cảnh báo theo điều kiện bạn đặt"]'::jsonb, 'cong cu|chin cong|chuyen nganh|luan chuyen|chin|kho du|moi|so huu|theo ma|kien|dieu kien|luan|du phong|luan diem|bi nhin|cap su|con lon|con room|cu bo|cu khac', null),
('s16-1', 51, '0.1.21', '16.1', 'Luận điểm', 'Insight: chín công cụ phân tích sâu (mới 0.1.20)', 'Tạo ý tưởng ở Nghiên Cứu → Ý tưởng, rồi mở Insight → Luận điểm và bấm Điều kiện trên ý tưởng đó. Chọn chỉ tiêu (giá, ROE, nợ/vốn, tăng trưởng, phòng khối ngoại, nội bộ mua ròng…), phép so, ngưỡng và mức độ: Quan trọng (sai nghĩa là luận điểm bị phá vỡ) hoặc Chú ý (cảnh báo)…', '["Luận điểm","Nghiên Cứu → Ý tưởng","Insight → Luận điểm","Điều kiện","Đã xảy ra","Không","Quan trọng","Chú ý","sự kiện tự xác nhận","email cho bạn một lần"]'::jsonb, 'luan diem|dieu kien|bi pha|pha vo|so lieu|kien|pha|vo|luan|tuong|bam dieu|bat da|bi coi|bo mua|cap phep|chup cuoi|diem tao|do chon|dung su|ghi lan', null),
('s16-2', 52, '0.1.21', '16.2', 'Thanh khoản và sức chứa', 'Insight: chín công cụ phân tích sâu (mới 0.1.20)', 'Ngày thoát = số cổ phiếu / (tỷ lệ tối đa × khối lượng bình quân ngày). Tác động giá theo cùng công thức căn bậc hai của Market Simulation, chia đều số phiên cần để bán. Hệ số quy mô: nhân cả danh mục lên tối đa mấy lần thì mọi vị thế vẫn thoát được trong số phiên đã chọn, và mã…', '["Thanh khoản và sức chứa","Ngày thoát","Tác động giá","Hệ số quy mô","đã vượt","Ứng viên"]'::jsonb, 'phien da|trongso phien|thoat|da chon|suc chua|khoi luong|so quy|phien|bac hai|cham san|chan truoc|chia deu|chua ngay|cung cong|da khoi|da may|da vuot|dam thanh|deu so|du dinh', null),
('s16-3', 53, '0.1.21', '16.3', 'Dòng tiền', 'Insight: chín công cụ phân tích sâu (mới 0.1.20)', 'Gộp cổ tức tiền (đã công bố hoặc ước tính theo khoản đã trả, đã trừ thuế 5%), tiền bán chưa về (ngày T+2, bỏ cuối tuần và ngày nghỉ lễ), đề xuất lệnh đang chờ hoặc đã duyệt chưa khớp, lệnh dự kiến bạn tự thêm, và lãi vay nếu bạn nhập lãi suất. Trang cho biết ngày thiếu tiền đầu…', '["Dòng tiền","tiền triển khai được"]'::jsonb, 'du thap|lenh du|thap nhat|tien|du kien|nghi le|so du|lenh|bo cuoi|bo hoac|bo lich|chan lenh|chua day|chua khop|chua ve|da tra|da tru|du nen|duyet chua|hoac uoc', null),
('s16-4', 54, '0.1.21', '16.4', 'Sở hữu', 'Insight: chín công cụ phân tích sâu (mới 0.1.20)', 'Giao dịch nội bộ là thông tin công bố: người liên quan đăng ký mua / bán rồi mới thực hiện. Trang tách giao dịch đã thực hiện (tính vào mua / bán ròng) khỏi đăng ký (ý định, chưa chắc xảy ra; hết hạn thì không còn tính). Mua đồng loạt: từ 3 người khác nhau cùng mua thật trong…', '["Sở hữu","Đồng bộ","Giao dịch nội bộ","công bố","đăng ký","đã thực hiện","Mua đồng loạt","Phòng khối ngoại"]'::jsonb, 'dang ky|thuc hien|mua|dong bo|lien quan|giao dich|bo|bam dong|bo ngay|bo nguoi|chac xay|con duoi|con tinh|da thuc|dich da|dich noi|dinh chua|don le|dong loat|dong rat', null),
('s16-5', 55, '0.1.21', '16.5', 'Luân chuyển ngành', 'Insight: chín công cụ phân tích sâu (mới 0.1.20)', 'Mỗi chấm là một chỉ số ngành HOSE so với VN-Index, kiểu Relative Rotation Graph: ngang là sức mạnh tương đối so với xu hướng dài của chính nó (RS-Ratio), dọc là đà (RS-Mom). Bốn góc: Dẫn đầu, Suy yếu, Tụt hậu, Cải thiện; ngành thường đi vòng theo chiều Cải thiện → Dẫn đầu → Suy…', '["Luân chuyển ngành","Dẫn đầu","Suy yếu","Tụt hậu","Cải thiện","tự tính"]'::jsonb, 'dau suy|suy yeu|tut hau|yeu tut|hau|tut|cai thien|rs|suy|bon goc|chieu cai|chua gom|da rs|graph ngang|hau cai|hose so|index kieu|kieu relative|mem khac|moi cham', null),
('s16-6', 56, '0.1.21', '16.6', 'Độ chính xác dự phóng', 'Insight: chín công cụ phân tích sâu (mới 0.1.20)', 'Chấm bốn thứ: giá trị hợp lý đã lưu ở Valuation Bench (kỳ 3 / 6 / 12 tháng, từng phương pháp, từng người lập), ý tưởng (đã duyệt, đang trong danh mục hoặc đã đóng), quyết định trong Nhật Ký Quyết Định, và dự phóng lợi nhuận / doanh thu bạn ghi ngay tại trang.', '["Độ chính xác dự phóng","giá trị hợp lý","ý tưởng","dự phóng lợi nhuận / doanh thu","so với VN-Index cùng kỳ","mẫu nhỏ","không sửa được"]'::jsonb, 'du phong|phong loi|tu tin|quyet dinh|quyet|ty le|cham|phong|bench ky|bon thu|cham bon|cham khi|cham sai|chu dat|cong that|cung ky|da dong|da du|dong quyet|du ky', null),
('s16-7', 57, '0.1.21', '16.7', 'Kho dữ liệu theo thời điểm', 'Insight: chín công cụ phân tích sâu (mới 0.1.20)', 'Mỗi ngày làm việc lúc 19:05 hệ thống chụp chỉ số của cả thị trường (khoảng 1.500 mã) theo ngày của số liệu; mỗi khi báo cáo tài chính một mã đổi thì thêm một dòng kèm ngày lần đầu thấy; tin các báo được lưu mỗi 3 giờ. Mục đích: sau này backtest chiến lược chạy trên số liệu đúng…', '["Kho dữ liệu theo thời điểm","lần đầu thấy","đúng như đã thấy vào ngày đó"]'::jsonb, 'ngay|so lieu|lieu|chup|ngay thieu|tu nguon|nguon|cong bo|so|du lieu|backtest chien|bi nguon|biet kho|bo that|bu nguoc|chinh da|chup ngay|cu dung|da chup|dau chup', null),
('s16-8', 58, '0.1.21', '16.8', 'Việc cần làm (mới)', 'Insight: chín công cụ phân tích sâu (mới 0.1.20)', 'Mỗi công cụ ở trên có tín hiệu riêng nằm ở một tab; nguy cơ là bạn không mở hết. Insight → Việc cần làm gom mọi tín hiệu đã có thành một danh sách bốn mức khẩn cấp: nghiêm trọng (nên xem ngay), cao (trong ngày), vừa (trong tuần), thông tin.', '["Việc cần làm","Insight → Việc cần làm","Vì sao một mục nằm ở mức này?","đã có","nghiêm trọng","vừa","thông tin","đang nắm","Email buổi sáng:","chỉ gửi khi có mục mới"]'::jsonb, 'nghiem|email|muc|muc nghiem|tin|tin hieu|moi muc|moi|bam vi|bi loi|bon muc|cao so|cao tin|cap nghiem|cham gioi|chap no|chay bi|cuoc cung|dich giai|duyet canh', null),
('s16-9', 59, '0.1.21', '16.9', 'Sự kiện theo mã (mới)', 'Insight: chín công cụ phân tích sâu (mới 0.1.20)', 'Máy chủ đọc tin các báo mỗi 3 giờ, gắn mã cổ phiếu có trong tiêu đề, rồi nhận ra tin nói về việc gì bằng luật từ khoá: kết quả kinh doanh, cổ tức, phát hành, mua lại, nhân sự cấp cao, hợp đồng, giải chấp, đình chỉ, pháp lý, người trong cuộc mua bán, dòng tiền khối ngoại, khuyến…', '["Sự kiện theo mã","Insight → Sự kiện","nói về việc gì","cụm từ đã khớp","Hướng"]'::jsonb, 'cum tu|tin|tu da|theo ma|ngu|cum|tieu|tu|ma|bi xep|bo sot|cao hop|cap cao|cay thap|chu doc|cuoc mua|da khop|da nghia|dau tich|diem vi', null),
('s17', 60, '0.1.21', '17', 'Phòng kiểm thử: thử chiến lược trên lịch sử và phân rã lợi suất (mới 0.1.20)', 'Phòng kiểm thử: thử chiến lược trên lịch sử và phân rã lợi suất (mới 0.1.20)', 'Trang Kiểm thử (thanh điều hướng của Investment Workbench) có hai tab. Mọi phép tính chạy ngay trong máy bạn; kho giá tải về một lần (lần đầu khoảng 1–2 phút) rồi lưu trên máy, các lần sau chỉ tải thêm ngày mới. Kết quả chỉ được lưu lên máy chủ khi bạn bấm Lưu, và chỉ chủ lần…', '["Phòng kiểm thử: thử chiến lược trên lịch sử và phân rã lợi suất","Phòng kiểm thử","Kiểm thử","ngay trong máy bạn"]'::jsonb, 'kiem thu|thu chien|chien luoc|lan|thu|kiem|chay ngay|chu khi|chu lan|dau khoang|hai tab|lan kiem|lan lan|lan sau|luoc tren|luu len|moi phep|phep tinh|phut roi|ra loi', null)
insert into public.butler_guide (id, ord, ver, n, t, ct, s, k, w, p) values
('s17-1', 61, '0.1.21', '17.1', 'Kiểm thử chiến lược', 'Phòng kiểm thử: thử chiến lược trên lịch sử và phân rã lợi suất (mới 0.1.20)', 'Chọn một mẫu (Động lượng 12-1, Biến động thấp, Xu hướng tăng, Rẻ và chất lượng, Đảo chiều tuần, Tăng trưởng lợi nhuận) hoặc tự dựng: vũ trụ và giai đoạn, bộ lọc, tiêu chí xếp hạng có trọng số, số mã và cách chia tỷ trọng, tần suất cân bằng, độ trễ khớp, chi phí.', '["Kiểm thử chiến lược","Chạy kiểm thử","Có đáng tin không?","có tại thời điểm đó","khác nhau"]'::jsonb, 'tru|ma ket|so cau|so lai|sharpe|vu tru|dep|chua du|so|thu|cau|kiem thu|giai doan|ma|bam chay|bang he|bi huy|ca ma|cang nhieu|chia ty', null),
('s17-2', 62, '0.1.21', '17.2', 'Yếu tố: danh mục lãi hay lỗ vì đâu', 'Phòng kiểm thử: thử chiến lược trên lịch sử và phân rã lợi suất (mới 0.1.20)', 'Chọn đối tượng (danh mục của tôi, danh mục nhóm hoặc vài mã tự chọn, ví dụ FPT:40 HPG:30 VCB:30) và cửa sổ 1 / 2 / 3 năm. Hệ thống dựng lợi suất năm yếu tố mua-bán từ kho giá (quy mô nhỏ, giá trị rẻ, động lượng, biến động thấp, chất lượng) cùng yếu tố thị trường, rồi hồi quy…', '["Yếu tố: danh mục lãi hay lỗ vì đâu","Yếu tố","FPT:40 HPG:30 VCB:30","t-stat","tỷ trọng hiện tại"]'::jsonb, 'yeu to|to|yeu|hoi quy|danh muc|he so|alpha con|ap nguoc|chon vi|cung yeu|da giu|dau chon|do nghieng|doc khi|dung ty|fama french|gia quy|giu that|hoac vai|khi he', null),
('s18', 63, '0.1.21', '18', 'Nối các màn, đối soát kế toán, nhật ký kiểm toán và kiểm tra hệ thống (mới 0.1.20)', 'Nối các màn, đối soát kế toán, nhật ký kiểm toán và kiểm tra hệ thống (mới 0.1.20)', 'Các khu của Investment Workbench (Danh Mục, Nghiên Cứu, Valuation, Insight, Kiểm thử, Mô phỏng, Thị trường, Toàn Nhóm) giờ nối với nhau: từ một mã cổ phiếu hay một việc cần làm, bạn nhảy thẳng sang màn liên quan mà không phải tự tìm lại mã.', '["Nối các màn, đối soát kế toán, nhật ký kiểm toán và kiểm tra hệ thống"]'::jsonb, 'kiem toan|ky kiem|tra he|nhat ky|kiem|toan|ke toan|gio noi|nhau tu|nhay thang|nhom gio|phai tu|quan ma|soat ke|thang sang|thong moi|toan nhat|truong toan|workbench danh|he thong', null),
('s18-1', 64, '0.1.21', '18.1', 'Mã bấm được và menu “…”', 'Nối các màn, đối soát kế toán, nhật ký kiểm toán và kiểm tra hệ thống (mới 0.1.20)', 'Bấm vào mã (bảng danh mục, theo dõi, rủi ro, sự kiện, lệnh, tin ở trang Thị trường, kết quả Insight, Mô phỏng…) mở hồ sơ định giá của mã trong Valuation Bench. Mã chưa có hồ sơ thì mở Valuation thay vì báo lỗi. Nút “…” cạnh mã mở menu: Nghiên cứu, Luận điểm, Sự kiện, Sở hữu…', '["Mã bấm được và menu “…”","Đang xem mã","#liquidity/FPT","#runs/…","Bấm vào mã","Nút “…” cạnh mã","Việc cần làm"]'::jsonb, 'diem su|kien so|ma|su kien|insight|so huu|luan diem|dia|menu|bench ma|canh ma|chep dia|chia se|cuu luan|dang loc|dau vi|dich gioi|do viec|doi rui|du liquidity', null),
('s18-2', 65, '0.1.21', '18.2', 'Nhật ký mô phỏng: của tôi và cả nhóm', 'Nối các màn, đối soát kế toán, nhật ký kiểm toán và kiểm tra hệ thống (mới 0.1.20)', 'Ở Market Simulation > Nhật ký, nút Của tôi / Cả nhóm chọn xem lần chạy của riêng bạn hay của mọi thành viên; mỗi lần chạy ghi rõ người chạy. Bạn chỉ lưu, đánh dấu sự kiện và xoá được lần chạy của chính mình (lần chạy của người khác chỉ xem); phần “học độ lớn cú sốc” chỉ dùng…', '["Nhật ký mô phỏng: của tôi và cả nhóm","Nhật ký mô phỏng","Của tôi","Cả nhóm","người chạy"]'::jsonb, 'lan chay|chay|lan|ca nhom|chay ghi|luu danh|nguoi chay|nhom chon|phan hoc|ro nguoi|simulation nhat|vien moi|nhat ky|moi thanh|cu soc|dau su|do lon|hoc do|lon cu|ghi ro', null),
('s18-3', 66, '0.1.21', '18.3', 'Nhật Ký Kiểm Toán', 'Nối các màn, đối soát kế toán, nhật ký kiểm toán và kiểm tra hệ thống (mới 0.1.20)', 'Mục Nhật Ký Kiểm Toán (trang chủ, dành cho quản trị) ghi ai làm gì, khi nào trên các bảng dữ liệu quan trọng, gồm nay cả các bảng tài chính: lệnh, hành động doanh nghiệp, giới hạn đầu tư và ngoại lệ, duyệt lệnh, ý tưởng, luận điểm, nhật ký quyết định, lần chạy mô phỏng và kiểm…', '["Nhật Ký Kiểm Toán","ai làm gì, khi nào","tự động ở cơ sở dữ liệu"]'::jsonb, 'nhat ky|kiem toan|ky kiem|chinh lenh|chu danh|diem nhat|dinh lan|ghi ai|ghi tu|le duyet|loai doi|nghiep gioi|ngoai le|nguoi theo|nhom nhat|thuoc app|toan muc|tri ghi|tuong luan|xoa dong', null),
('s18-4', 67, '0.1.21', '18.4', 'Liên kết web kế toán', 'Nối các màn, đối soát kế toán, nhật ký kiểm toán và kiểm tra hệ thống (mới 0.1.20)', 'Ở Danh Mục > Báo Cáo, thẻ Liên kết kế toán cho thấy web kế toán (OnyxLine Accounting) sẽ nhận gì từ sổ lệnh của bạn trong một tháng: bút toán theo hệ thống tài khoản TT200 (mua, bán, cổ tức, dự phòng giảm giá…). Phần đối soát nay soát hai chiều:', '["Liên kết web kế toán","Báo Cáo","Liên kết kế toán","Chưa gửi / bị từ chối","Mồ côi","Dự phòng bổ sung","không tự sửa hay tự đảo","một sổ chung"]'::jsonb, 'chung tu|da ghi|ke toan|ghi so|web ke|nghiep vu|tu|chung|so|gui|web|da gui|gui lai|roi gui|so cai|tu choi|toan|ke|but toan|giam gia', null),
('s18-5', 68, '0.1.21', '18.5', 'Kiểm tra hệ thống', 'Nối các màn, đối soát kế toán, nhật ký kiểm toán và kiểm tra hệ thống (mới 0.1.20)', 'Menu tài khoản (góc trên bên phải) > Kiểm tra hệ thống thử từng thứ app cần: phiên đăng nhập, giá trực tiếp, nguồn dự phòng, lịch nghỉ lễ, ghi tệp, thông báo, ảnh chụp thị trường, dữ liệu định giá. Nay có thêm hai mục phía máy chủ: lịch chạy nền (pg_cron) (có lịch nào lỗi hay…', '["Kiểm tra hệ thống","lịch chạy nền (pg_cron)","dữ liệu nền cập nhật đúng hạn"]'::jsonb, 'chay nen|dang nhap|lich chay|lich he|thong hoac|he thong|lich|tra he|ham|thong|cap nhat|he|kiem tra|chay|nhap|nhat|du lieu|biet ham|chay qua|chu cap', null),
('s19', 69, '0.1.21', '19', 'Quản gia: hỏi đáp, chỉ đường và hướng dẫn ngay trong app (mới 0.1.21)', 'Quản gia: hỏi đáp, chỉ đường và hướng dẫn ngay trong app (mới 0.1.21)', 'Quản gia là trợ lý ở góc dưới bên phải của các màn hình Fin. Bạn hỏi bằng tiếng Việt (có dấu hay không dấu đều được); Quản gia chỉ đường tới đúng chức năng, cho biết hôm nay bạn có việc gì, đọc số liệu trong phạm vi quyền của bạn và giải thích các khái niệm theo chính tài liệu…', '["Quản gia: hỏi đáp, chỉ đường và hướng dẫn ngay trong app","Quản gia","bản thử"]'::jsonb, 'quan gia|quan|bang tieng|hoi bang|hoi dap|tro ly|vi quyen|hoi|app moi|dau deu|doc so|dung ai|dung chuc|gia hoi|niem theo|pham vi|roi may|theo chinh|tieng viet|dung', null),
('s19-1', 70, '0.1.21', '19.1', 'Mở Quản gia và hỏi gì', 'Quản gia: hỏi đáp, chỉ đường và hướng dẫn ngay trong app (mới 0.1.21)', 'Bấm nút Quản gia ở góc dưới bên phải hoặc nhấn Alt+J; Esc để đóng. Nút Xoá hội thoại làm sạch khung chat (hội thoại chỉ lưu tạm trong phiên làm việc). Quản gia có mặt ở trang chính và các khu Investment, Valuation, Insight, Kiểm thử, Mô phỏng, Thị trường. Khi bạn đang xem một…', '["Mở Quản gia và hỏi gì","Quản gia","Xoá hội thoại","Cách làm","Mở","Đọc trong hướng dẫn","Biết vào đâu, làm thế nào","Biết hôm nay có gì","Xem số liệu","Hiểu một khái niệm hay cách đọc","Alt+J","Esc"]'::jsonb, 'quan gia|hoi|hoi ve|chuc nang|chuc|hoi thoai|nhom finance|nhom gioi|nang|dang giu|muc ca|cau hoi|quan|cau|han|nhom|qua han|gioi han|nguoi khac|dung', null),
('s19-2', 71, '0.1.21', '19.2', 'Hướng dẫn sử dụng trong app', 'Quản gia: hỏi đáp, chỉ đường và hướng dẫn ngay trong app (mới 0.1.21)', 'Toàn bộ hướng dẫn này nay đọc được ngay trong app, không cần mở tệp PDF: mở địa chỉ /guide/ hoặc bấm nút Đọc trong hướng dẫn ở thẻ Quản gia. Mỗi mục có địa chỉ riêng (ví dụ /guide/#s4-4 cho mục 4.4) nên Quản gia mở đúng chỗ cần đọc; mục được chọn tô nền vàng nhạt. Nút Quay lại…', '["Hướng dẫn sử dụng trong app","Đọc trong hướng dẫn","Quay lại WorkHub Fin","Luôn khớp phiên bản","Khác bản PDF ở hình minh hoạ","/guide/","/guide/#s4-4"]'::jsonb, 'quan gia|pdf|guide|app|dia|app toan|bang chu|bo cai|cai gon|chon to|chu thich|cung sinh|doc muc|du guide|gia cung|guide hoac|guide s4|hai noi|khop phien|kien thuc', null),
('s19-3', 72, '0.1.21', '19.3', 'Quản gia dùng AI thế nào và dữ liệu nào rời máy bạn', 'Quản gia: hỏi đáp, chỉ đường và hướng dẫn ngay trong app (mới 0.1.21)', 'Quản gia xử lý bằng quy tắc trước (nhận diện từ khoá tiếng Việt, đối chiếu danh mục chức năng và chỉ mục hướng dẫn), nên phần lớn câu hỏi được trả lời ngay mà không dùng AI. Chỉ khi quy tắc không chắc, Quản gia nhờ Gemini của Google (gói miễn phí) chọn mục phù hợp trong danh…', '["Quản gia dùng AI thế nào và dữ liệu nào rời máy bạn","Dùng AI (Gemini miễn phí, bản thử)","quy tắc trước","Gemini của Google (gói miễn phí)","không","câu hỏi của bạn","không bao giờ","đừng gõ thông tin nhạy cảm vào câu hỏi","30 lượt AI mỗi ngày"]'::jsonb, 'quan gia|noi dung|quy tac|cau hoi|tra loi|mien phi|dung ai|ai|cau|dung|mien|goi mien|van tra|gemini|gia van|han muc|noi|bang quy|hoi|google', null)
insert into public.butler_guide (id, ord, ver, n, t, ct, s, k, w, p) values
('s19-4', 73, '0.1.21', '19.4', 'Giới hạn và cách dùng đúng', 'Quản gia: hỏi đáp, chỉ đường và hướng dẫn ngay trong app (mới 0.1.21)', 'Quản gia chỉ đọc: không tạo, sửa, xoá hay duyệt bất cứ thứ gì thay bạn. Muốn làm, bấm nút Mở rồi tự thao tác. Thấy đúng những gì bạn được thấy: Quản gia hỏi dữ liệu bằng chính phiên đăng nhập của bạn nên quyền theo nhóm, vai trò và phân quyền Finance được giữ nguyên. Hết phiên…', '["Giới hạn và cách dùng đúng","Mở","Quản gia chỉ đọc","Thấy đúng những gì bạn được thấy","Có thể hiểu sai ý","Mất kết nối máy chủ","Chỉ có trong app"]'::jsonb, 'quan gia|dang nhap|app chua|chinh phien|chon cau|chu quan|chua gan|cu thu|du ten|dung bam|dung duoi|dung quan|duoi cau|duyet bat|email telegram|gan email|hieu sai|hoi du|hoi lai|khac vi', null),
('pa', 74, '0.1.21', '', 'Phụ lục A: 10 mô hình kinh doanh và vai trò phương pháp', 'Phụ lục A: 10 mô hình kinh doanh và vai trò phương pháp', 'Bảng do ứng dụng dùng thật (sinh trực tiếp từ mã nguồn). Vai trò mặc định; bạn đổi được trong tab Quy trình. Phương pháp nào chưa tính được (ví dụ cần bạn nhập NAV) sẽ hiện là lỗ hổng nếu là Chính hoặc Hỗ trợ. Lợi nhuận và dòng tiền khá ổn định, tăng trưởng vừa phải: dòng tiền…', '["Phụ lục A: 10 mô hình kinh doanh và vai trò phương pháp","Phụ lục A","Chính (trọng số 2,5)","Hỗ trợ (1,2)","Đối chiếu (0,5)","Tham khảo (0, chỉ hiển thị)"]'::jsonb, 'theo lich|chinh no|nganh|chinh|graham|so|chinh nav|chinh trongso|tuc gordon|lich su|doanh|tien doanh|dcf dong|nghiep fcff|rong dieu|san rong|so graham|nganh ev|nganh ho|phan sotp', null),
('pb', 75, '0.1.21', '', 'Phụ lục B: thư viện phương pháp', 'Phụ lục B: thư viện phương pháp', 'Danh sách các phương pháp, chỉ báo và bước tổng hợp trong Valuation Bench, kèm công thức chính. Định nghĩa đầy đủ, cách dùng, giới hạn và cách đọc có trong ứng dụng ở mục Phương pháp.', '["Phụ lục B: thư viện phương pháp","Phụ lục B","DCF dòng tiền doanh nghiệp (FCFF)","FCFE nhiều giai đoạn","Thu nhập thặng dư (Residual Income)","P/B hợp lý = (ROE − g) / (Ke − g)","DCF ngược (điều gì phải đúng)","Mô phỏng Monte Carlo","Kịch bản bi quan / cơ sở / lạc quan","Dải bội số lịch sử của chính cổ phiếu","PEG và P/E hợp lý của Lynch","Bộ mã so sánh tự chọn","Giá trị sức sinh lời (EPV) của Greenwald","NCAV (Graham net-net)","Tổng các phần (SOTP)","Phân rã DuPont","ROIC so với WACC","Piotroski F-score (9 tiêu chí)","Altman Z","Beneish M-score (8 biến)","Chỉ số ngân hàng","ADX và +DI / −DI","Ichimoku (mây)","Supertrend và Parabolic SAR","RSI (Wilder 14)","MACD (12, 26, 9)","Stochastic và StochRSI","CCI và Williams %R","ATR, biến động lịch sử và sụt giảm","OBV, CMF, MFI, A/D, VWAP","Điểm xoay và Fibonacci","Hỗ trợ / kháng cự theo cụm","Mẫu nến","Phân kỳ RSI - giá","Sức mạnh tương đối so với VN-Index","Vòng quay sức mạnh ngành (JdK RS)","Bảng điểm độ chính xác (backtest)","Biểu đồ khoảng giá và giá trị đồng thuận","Biên an toàn và vùng giá tham khảo","Độ tin cậy của định giá","Mô hình cổ tức (Gordon, hai giai đoạn, H-model)","Bội số ngang hàng (P/E, P/B, P/S, EV/EBITDA, EV/Doanh thu)","Lợi suất lợi nhuận và phần bù so với trái phiếu","Số Graham và công thức tăng trưởng của Graham","Giá trị tài sản ròng điều chỉnh (NAV / RNAV)","Chỉ số dồn tích Sloan và chuyển hoá lợi nhuận thành tiền","Vòng quay vốn lưu động (DSO, DIO, DPO, CCC)","Tăng trưởng bền vững và tăng trưởng lịch sử","Xu hướng: đường trung bình (SMA/EMA 20, 50, 100, 200)","Bollinger, Keltner, Donchian và nén biến động"]'::jsonb, 'muc phuong|phap cong|gia|cong thuc|gia tri|bvps|so|phuong phap|eps|rs|trung binh|thap|von|dong|boi so|roe|tri|phuong|trung|wacc', null),
('pc', 76, '0.1.21', '', 'Phụ lục C: thuật ngữ', 'Phụ lục C: thuật ngữ', 'Biên an toàn 1 − giá / giá trị hợp lý. Càng cao, giá càng thấp hơn giá trị ước tính. CAGR Tốc độ tăng trưởng kép hằng năm. DCF Chiết khấu dòng tiền: giá trị hiện tại của các dòng tiền tương lai. EBIT, EBITDA Lợi nhuận trước lãi vay và thuế; thêm khấu hao thì là EBITDA. EPV Giá…', '["Phụ lục C: thuật ngữ","Phụ lục C"]'::jsonb, 'gia tri|gia|loi nhuan|tri|phi von|tren von|von|nhuan|loi|von chu|dong tien|dong|doanh|do icb|doanh nopat|dong ic|ket fcff|lai ebit|lai var|nam dcf', null),
